/**
 * Flush local diagnostics, durable execution history, and process output at
 * the same boundaries.
 *
 * The lifecycle is running, terminal, then process death when applicable.
 * Process death updates durable state and output while the local diagnostic
 * stays running, preventing a stale terminal record from being reused.
 * Between running and terminal, {@link refreshStartLogWhile} refreshes only
 * process output.
 */
import { hostedErrorStackSnippet, writeHostedExecutionDiag, } from "./hosted-execution-diag.js";
import { serializeSessionRunError, snapshotSessionRunLogs, } from "./session-run-log.js";
const MAX_ERROR_MESSAGE_LENGTH = 1024;
function boundedMessage(text) {
    return text.length > MAX_ERROR_MESSAGE_LENGTH
        ? `${text.slice(0, MAX_ERROR_MESSAGE_LENGTH)}…`
        : text;
}
/** The guest-disk diagnostic the host reads after a failed execute. */
export async function writeLocalHostedExecutionRecord(sinks, fields, writtenAt) {
    if (sinks.stateRoot !== undefined) {
        const message = fields.message === undefined ? undefined : boundedMessage(fields.message);
        const stack = fields.error === undefined ? undefined : hostedErrorStackSnippet(fields.error);
        await writeHostedExecutionDiag(sinks.stateRoot, {
            v: 1,
            executionId: fields.executionId,
            writtenAt,
            sessionPublicId: fields.sessionPublicId,
            sessionId: fields.sessionId,
            turnStatus: fields.turnStatus,
            durationMs: fields.durationMs,
            ...(message === undefined ? {} : { message }),
            ...(stack === undefined || stack.length === 0 ? {} : { stack }),
            signalAborted: fields.abortReason === "signal_abort" ? true : undefined,
            ...(fields.abortReason === undefined ? {} : { abortReason: fields.abortReason }),
            failureCode: fields.failureCode,
            ...(fields.errorCode === undefined ? {} : { errorCode: fields.errorCode }),
            classification: fields.classification,
        });
    }
}
/**
 * Store-backed execution history and process output. Never rejects. Both
 * sinks start synchronously, so their crash-flush state is stamped before
 * either store round trip.
 */
export async function flushDurableHostedExecutionRecord(sinks, fields, writtenAt) {
    const writes = [];
    if (sinks.persistSessionRun !== undefined) {
        const message = fields.message === undefined ? undefined : boundedMessage(fields.message);
        const error = fields.error === undefined ? undefined : serializeSessionRunError(fields.error);
        writes.push(sinks.persistSessionRun({
            executionId: fields.executionId,
            writtenAt,
            sessionPublicId: fields.sessionPublicId,
            sessionId: fields.sessionId,
            turnStatus: fields.turnStatus,
            durationMs: fields.durationMs,
            ...(fields.abortReason === undefined ? {} : { abortReason: fields.abortReason }),
            ...(message === undefined ? {} : { message }),
            ...(error === undefined ? {} : { error }),
            logs: snapshotSessionRunLogs(sinks.snapshotLogs?.() ?? []),
        }));
    }
    if (sinks.flushStartLog !== undefined) {
        writes.push(sinks.flushStartLog(fields.sessionPublicId));
    }
    // Soft-fail: a store outage must not change the HTTP reply.
    await Promise.allSettled(writes);
}
/**
 * Each refresh is a store write on the deployment's shared write budget, so
 * keep it coarse. An unchanged tee costs nothing (the store skips the put).
 */
export const HOSTED_START_LOG_REFRESH_INTERVAL_MS = 30_000;
/**
 * Refresh the tee while `run` (the turn) settles: v2 has no engine to tail,
 * so this snapshot is the only view of a running turn. A tick is skipped
 * while a refresh is still in flight, and the last one settles before this
 * returns so it cannot land after the terminal flush.
 */
export async function refreshStartLogWhile(sinks, startLogId, run) {
    const flush = sinks.flushStartLog?.bind(sinks);
    if (flush === undefined) {
        return await run();
    }
    let refresh;
    const timer = setInterval(() => {
        // Soft-fail like the other flushes. A rejection left unhandled here would
        // trip the process-death flush.
        refresh ??= flush(startLogId)
            .catch(() => undefined)
            .finally(() => {
            refresh = undefined;
        });
    }, HOSTED_START_LOG_REFRESH_INTERVAL_MS);
    try {
        return await run();
    }
    finally {
        clearInterval(timer);
        await refresh;
    }
}
/**
 * Durable-only crash flush. Leaves `hosted-execution.json` at `running`.
 */
export async function flushHostedExecutionProcessDeath(args) {
    await args.flushProcessDeath(args.reason, args.error);
    if (args.startLogId !== undefined && args.flushStartLog !== undefined) {
        await args.flushStartLog(args.startLogId);
    }
}
